import test from 'node:test';
import assert from 'node:assert/strict';
import { getCustomer, normalizeId, listCustomers, validateCustomer } from '../src/customers.js';

test('normalizeId trims whitespace', () => {
  assert.equal(normalizeId('C-001 '), 'C-001');
  assert.equal(normalizeId(' C-001'), 'C-001');
  assert.equal(normalizeId(' C-001 '), 'C-001');
});

test('normalizeId converts to uppercase', () => {
  assert.equal(normalizeId('c-001'), 'C-001');
  assert.equal(normalizeId('c-007'), 'C-007');
  assert.equal(normalizeId('C-001'), 'C-001');
});

test('normalizeId handles mixed case and spaces', () => {
  assert.equal(normalizeId('c-007 '), 'C-007');
  assert.equal(normalizeId(' c-001 '), 'C-001');
  assert.equal(normalizeId('  C-003  '), 'C-003');
});

test('normalizeId with non-string input', () => {
  assert.equal(normalizeId(1), '1');
  assert.equal(normalizeId(true), 'TRUE');
});

test('getCustomer finds customer with exact ID', () => {
  const result = getCustomer('C-001');
  assert.equal(result.ok, true);
  assert.equal(result.value.name, 'Northwind Studio');
});

test('getCustomer finds customer with lowercase ID', () => {
  const result = getCustomer('c-001');
  assert.equal(result.ok, true);
  assert.equal(result.value.name, 'Northwind Studio');
});

test('getCustomer finds customer with spaces around ID', () => {
  const result = getCustomer(' c-001 ');
  assert.equal(result.ok, true);
  assert.equal(result.value.name, 'Northwind Studio');
});

test('getCustomer finds customer with mixed case and spaces', () => {
  const result = getCustomer('  C-007  ');
  assert.equal(result.ok, true);
  assert.equal(result.value.name, 'Halvorsen Architects');
});

test('getCustomer reports unknown ID with normalized lookup', () => {
  const result = getCustomer('c-999');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('listCustomers returns copies', () => {
  const customers = listCustomers();
  const customers2 = listCustomers();
  assert.notStrictEqual(customers, customers2);
});

test('validateCustomer needs an id, a name and an email', () => {
  const valid = validateCustomer({ id: 'C-001', name: 'Test', email: 'test@example.com' });
  assert.equal(valid.ok, true);
  const noId = validateCustomer({ name: 'Test', email: 'test@example.com' });
  assert.equal(noId.ok, false);
  const noName = validateCustomer({ id: 'C-001', email: 'test@example.com' });
  assert.equal(noName.ok, false);
  const noEmail = validateCustomer({ id: 'C-001', name: 'Test' });
  assert.equal(noEmail.ok, false);
  const badEmail = validateCustomer({ id: 'C-001', name: 'Test', email: 'invalid' });
  assert.equal(badEmail.ok, false);
});

