test('createInvoice handles UNKNOWN_SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'UNKNOWN', qty: 1 }],
  });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_SKU');
});

test('createInvoice does not mutate input', () => {
  const input = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  };
  const inputCopy = JSON.parse(JSON.stringify(input));
  createInvoice(input);
  assert.deepEqual(input, inputCopy);
});

test('createInvoice handles multiple lines with mixed validity (stops at first error)', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'INVALID', qty: 1 },
    ],
  });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_SKU');
});

test('createInvoice with products having different VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 2 },
    ],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].vatRate, 21);
  assert.equal(result.value.lines[1].vatRate, 9);
  assert.equal(result.value.lines[2].vatRate, 0);
});

test('lineTotal calculates qty times unitPrice', () => {
  const line = { qty: 10, unitPrice: 9500 };
  assert.equal(lineTotal(line), 95000);
});

test('lineTotal with qty of 1', () => {
  const line = { qty: 1, unitPrice: 120000 };
  assert.equal(lineTotal(line), 120000);
});

test('lineTotal with qty of 0', () => {
  const line = { qty: 0, unitPrice: 9500 };
  assert.equal(lineTotal(line), 0);
});

test('lineTotal with large quantities', () => {
  const line = { qty: 1000, unitPrice: 5000 };
  assert.equal(lineTotal(line), 5000000);
});

test('invoiceTotals calculates subtotal and total for single line', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier = 0% discount
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // DEV-HOUR: 21% VAT
  // subtotal = 5 * 9500 = 47500
  // vat = 47500 * 21 / 100 = 9975
  // total = 47500 + 9975 = 57475
  assert.deepEqual(totals, {
    subtotal: 47500,
    discount: 0,
    vat: 9975,
    total: 57475,
  });
});

test('invoiceTotals calculates subtotal and total for multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier = 0% discount
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // DEV-HOUR: 21% VAT, LOGO-PACK: 21% VAT
  // subtotal = 95000 + 120000 = 215000
  // vat = 95000 * 21 / 100 + 120000 * 21 / 100 = 19950 + 25200 = 45150
  // total = 215000 + 45150 = 260150
  assert.deepEqual(totals, {
    subtotal: 215000,
    discount: 0,
    vat: 45150,
    total: 260150,
  });
});

test('invoiceTotals with multiple lines of different products', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier = 0% discount
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'PRINT-A4', qty: 100 },
    ],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // DEV-HOUR: 21%, LOGO-PACK: 21%, PRINT-A4: 9%
  // subtotal = 95000 + 120000 + 3700 = 218700
  // vat = 95000 * 21 / 100 + 120000 * 21 / 100 + 3700 * 9 / 100
  //     = 19950 + 25200 + 333 = 45483
  // total = 218700 + 45483 = 264183
  assert.deepEqual(totals, {
    subtotal: 218700,
    discount: 0,
    vat: 45483,
    total: 264183,
  });
});

test('invoiceTotals with many lines', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier = 0% discount
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 8 },
      { sku: 'DEV-HOUR', qty: 12 },
      { sku: 'COPY-HOUR', qty: 4 },
      { sku: 'SUPPORT-HOUR', qty: 6 },
    ],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // All have 21% VAT
  // subtotal = 68000 + 114000 + 24000 + 43500 = 249500
  // vat = 249500 * 21 / 100 = 52395
  // total = 249500 + 52395 = 301895
  assert.deepEqual(totals, {
    subtotal: 249500,
    discount: 0,
    vat: 52395,
    total: 301895,
  });
});

test('addLine adds a new line to an invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const invoice = result.value;
  const updated = addLine(invoice, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(updated.ok, true);
  assert.equal(updated.value.lines.length, 2);
  assert.equal(updated.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(updated.value.lines[0].qty, 5);
  assert.equal(updated.value.lines[1].sku, 'LOGO-PACK');
  assert.equal(updated.value.lines[1].qty, 1);
  assert.equal(updated.value.lines[1].name, 'Logo package');
});

test('addLine increases qty for existing SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
