test('invoiceTotals calculates discount for single line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // subtotal = 10 * 9500 = 95000
  // discount = 95000 * 10 / 100 = 9500
  // lineAmount = 95000 - 9500 = 85500
  // vat = 85500 * 21 / 100 = 17955
  // total = 95000 - 9500 + 17955 = 103455
  assert.deepEqual(totals, {
    subtotal: 95000,
    discount: 9500,
    vat: 17955,
    total: 103455,
  });
});

